import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getHikingDaysData } from '@apps/Hiking/@helpers/hikingDays.helper';
import { getHikingEquip } from '@apps/Hiking/@services/equip.service';
import { getHikingDuty } from '@apps/Hiking/@services/hikingDuty.service';
import { getHikingJointlyEquipments } from '@apps/Hiking/@services/hikingJointlyEquipment.service';
import {
  getFoodAsync,
  getHikingMenuProductsAsync,
} from '@apps/Hiking/@services/hikingMenu.service';
import { getHikingSchedule } from '@apps/Hiking/@services/hikingSchedule.service';
import { getHikingTransfers } from '@apps/Hiking/@services/hikingTransfers.service';
import { IHikingEquip } from '@apps/Hiking/@types/equip.types';
import { IHikingDuty, IHikingScheduleItem } from '@apps/Hiking/@types/hiking.baseTypes';
import { IHikingJointlyEquipment } from '@apps/Hiking/@types/hikingJointlyEquipment.types';
import { IHikingMenuExtendedProduct, IHikingMenuFood } from '@apps/Hiking/@types/hikingMenu.types';
import { IHikingTransfer } from '@apps/Hiking/@types/hikingTransfers.types';
import HikingPrintDuty from '@apps/Hiking/print/HikingPrint/components/HikingPrintDuty';
import HikingPrintFood from '@apps/Hiking/print/HikingPrint/components/HikingPrintFood';
import HikingPrintSchedule from '@apps/Hiking/print/HikingPrint/components/HikingPrintSchedule';
import HikingPrintTransfers from '@apps/Hiking/print/HikingPrint/components/HikingPrintTransfers';
import HikingPrintUsersLoad from '@apps/Hiking/print/HikingPrint/components/HikingPrintUsersLoad';
import HikingPrintCommonEquipPage from '@apps/Hiking/print/HikingPrint/HikingPrintCommonEquipPage';
import HikingPrintFirstAidKit from '@apps/Hiking/print/HikingPrint/HikingPrintFirstAidKit';
import HikingPrintFrontPage from '@apps/Hiking/print/HikingPrint/HikingPrintFrontPage';
import HikingPrintJointlyEquipment from '@apps/Hiking/print/HikingPrint/HikingPrintJointlyEquipment';
import HikingPrintMembersPage from '@apps/Hiking/print/HikingPrint/HikingPrintMembersPage';
import HikingPrintPlanRouteDatesPage from '@apps/Hiking/print/HikingPrint/HikingPrintPlanRouteDatesPage';
import HikingPrintPlanRoutePage from '@apps/Hiking/print/HikingPrint/HikingPrintPlanRoutePage';
import HikingPrintRepairKit from '@apps/Hiking/print/HikingPrint/HikingPrintRepairKit';
import { getWorkoutTrackMarkupForCsvWorkoutIds } from '@apps/Workouts/@services/workoutTrackMarkup.service';
import { IWorkoutTrackMarkup } from '@apps/Workouts/@types/workoutTrackMarkup.types';
import WorkoutTrackMarkupTable from '@apps/Workouts/components/WorkoutMarkupEdit/components/WorkoutTrackMarkupTable';
import A4Page, { A4SubPage } from '@components/A4Page';
import PageLoader from '@components/PageLoader';
import PolylineInfo from '@components/PolylineInfo';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import { weekDays } from 'src/resources/dates';

import {
  getBaseRouteDataAsync,
  getRouteObjectsAsync,
} from '../../../Routes/@services/routes.service';
import { IBaseRouteObjectLine, IMapType, IRouteObject } from '../../../Routes/@types/routes.types';
import { getHikingDataAsync } from '../../@services/hiking.service';
import { getHikingGpx } from '../../@services/hikingResults.service';
import { IHikingData, IHikingGpx } from '../../@types/hiking.types';

const HikingResults = ({ id_hiking }: { id_hiking: number }) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [tracks, setTracks] = React.useState<IHikingGpx[]>([]);
  const [trackMarkups, setTrackMarkups] = React.useState<IWorkoutTrackMarkup[]>([]);
  const [hikingSchedule, setHikingSchedule] = React.useState<IHikingScheduleItem[]>([]);
  const [hikingFood, setHikingFood] = React.useState<IHikingMenuFood[]>([]);
  const [hikingDuty, setHikingDuty] = React.useState<IHikingDuty[]>([]);
  const [routeObjects, setRouteObjects] = React.useState<IRouteObject[]>([]);
  const [mapData, setMapData] = React.useState<IMapType>();
  const [hikingEquip, setHikingEquip] = React.useState<IHikingEquip[]>([]);
  const [jointlyEquipment, setJointlyEquipment] = React.useState<IHikingJointlyEquipment[]>([]);
  const [hikingTransfers, setHikingTransfers] = React.useState<IHikingTransfer[]>([]);

  const [products, setProducts] = React.useState<IHikingMenuExtendedProduct[]>([]);

  React.useEffect(() => {
    if (!id_hiking) {
      return;
    }

    const start = async () => {
      try {
        setIsLoading(true);

        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        if (hd.route.id) {
          const ro = await getRouteObjectsAsync(hd.route.id);
          setRouteObjects(ro);

          const md = await getBaseRouteDataAsync(hd.route.id);
          setMapData(md.typeData);
        }

        const tr = await getHikingGpx(id_hiking);
        setTracks(tr);

        const mu = await getWorkoutTrackMarkupForCsvWorkoutIds(
          tr.map((t) => t.id_workout_track).join(','),
        );

        setTrackMarkups(mu);

        await getHikingSchedule(id_hiking).then(setHikingSchedule);
        await getHikingDuty(id_hiking).then(setHikingDuty);
        await getFoodAsync({ id_hiking }).then(setHikingFood);
        await getHikingMenuProductsAsync(id_hiking).then(setProducts);
        await getHikingEquip(id_hiking).then(setHikingEquip);
        await getHikingTransfers(id_hiking).then(setHikingTransfers);
        await getHikingJointlyEquipments(id_hiking).then(setJointlyEquipment);

        if (hd.route.id) {
          await getRouteObjectsAsync(hd.route.id).then(setRouteObjects);

          const brd = await getBaseRouteDataAsync(hd.route.id);
          setMapData(brd.typeData);
        }
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!hikingData || !routeObjects || !mapData || !tracks) {
    return <PohAlert variant={AlertVariant.Danger}>Has no data</PohAlert>;
  }

  const daysData = getHikingDaysData({
    hikingSchedule,
    hikingDuty,
    hikingTransfers,
    hikingFood,
    products,
    hikingData,
  });

  return (
    <>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/results`, text: 'Результаты', active: true },
        ]}
      />
      <PohContainer>
        <HikingContext.Provider value={hikingData}>
          {/* <header className="d-print-none d-flex justify-content-center" style={{ gap: '8px' }}>
                header {hikingData.name}
            </header> */}
          <article>
            <HikingPrintFrontPage />
            <HikingPrintMembersPage />
            <HikingPrintPlanRoutePage
              routeObjects={routeObjects}
              mapType={mapData}
              results={tracks}
            />
            <HikingPrintPlanRouteDatesPage
              daysData={daysData}
              routeObjects={routeObjects}
              results={tracks}
            />
          </article>

          {daysData.map((dayData, i) => {
            const isMain =
              dayData.date.getTime() >= hikingData?.start.setHours(0, 0, 0, 0) &&
              dayData.date.getTime() <= hikingData?.finish.setHours(23, 59, 59, 999);

            return (
              <A4Page key={dayData.date.toISOString()}>
                <h2>
                  День {i + 1}. {dayData.date.toLocaleDateString()}
                  &nbsp;
                  <small>{weekDays[dayData.date.getDay()]}</small>
                  {isMain && (
                    <small className="text-success">
                      {' '}
                      {(dayData.date.getTime() - hikingData?.start.getTime()) /
                        1000 /
                        60 /
                        60 /
                        24 +
                        1}
                      -й ходовой
                    </small>
                  )}
                </h2>

                <PohRow className="mt-3">
                  <PohCol sm={dayData.duty.length > 0 ? 8 : 12}>
                    <HikingPrintSchedule dayData={dayData} />
                  </PohCol>

                  {dayData.duty.length > 0 && (
                    <PohCol sm={4}>
                      <HikingPrintDuty dayData={dayData} />
                    </PohCol>
                  )}
                </PohRow>

                {dayData.userLoad && <HikingPrintUsersLoad dayData={dayData} />}

                <HikingPrintFood
                  dayData={dayData}
                  hikingFood={hikingFood}
                  hikingData={hikingData}
                  products={products}
                />

                {tracks
                  .filter(
                    (tr) => tr.start.toLocaleDateString() === dayData.date.toLocaleDateString(),
                  )
                  .map((track) => {
                    const plannedRouteObject = routeObjects.find(
                      (ro) => ro.id === track.schedule?.routeObject?.id,
                    );

                    return (
                      <A4SubPage key={track.id}>
                        <h3>{track.name}</h3>

                        <PolylineInfo
                          points={track.track.map(({ point: [la, lo, al] }) => [la, lo, al ?? 0])}
                          timestamps={track.track.map((t) => t.date.getTime())}
                          secondaryPoints={
                            plannedRouteObject
                              ? ((plannedRouteObject as IBaseRouteObjectLine).points as [
                                  number,
                                  number,
                                  number,
                                ][])
                              : undefined
                          }
                          mapType={mapData}
                          height={500}
                        />
                        <h4>График движения</h4>
                        <WorkoutTrackMarkupTable
                          workout={{ track: track.track }}
                          markups={trackMarkups.filter(
                            (x) => x.id_workout_track === track.id_workout_track,
                          )}
                        />
                      </A4SubPage>
                    );
                  })}

                {dayData.transfers.length > 0 && (
                  <HikingPrintTransfers transfers={dayData.transfers} />
                )}
              </A4Page>
            );
          })}

          {!!jointlyEquipment.filter((x) => x.type == 'tent').length && (
            <HikingPrintJointlyEquipment
              jointlyEquipment={jointlyEquipment.filter((x) => x.type == 'tent')}
              type="tent"
            />
          )}

          {!!jointlyEquipment.filter((x) => x.type == 'watercraft').length && (
            <HikingPrintJointlyEquipment
              jointlyEquipment={jointlyEquipment.filter((x) => x.type == 'watercraft')}
              type="watercraft"
            />
          )}

          <HikingPrintCommonEquipPage equip={hikingEquip} />
          <HikingPrintFirstAidKit hikingData={hikingData} />
          <HikingPrintRepairKit hikingData={hikingData} />
        </HikingContext.Provider>
      </PohContainer>
    </>
  );
};

export default HikingResults;
